    public boolean isStrong() {
        return Boolean.TRUE.equals(getProp("strong", Boolean.class));
    }

    /** {@code lines}. Cut off with "…" after this many lines; the whole text then shows in a tooltip on hover (only when it was cut). 1 keeps it on one line. */
