    public Double getLines() {
        return getProp("lines", Double.class);
    }

    /** {@code selectable}. People can select and copy it: the I-beam pointer, drag or click to highlight (two clicks a word, three a sentence, ...), Copy on a right-click. True by default (text is content); false for text that is part of the controls, or use Label. */
